ALTER TABLE agent_configurations ADD COLUMN model_protocol text NOT NULL DEFAULT '', ADD COLUMN model_name text NOT NULL DEFAULT '', ADD COLUMN model_base_url text NOT NULL DEFAULT '';
ALTER TABLE agent_configuration_versions ADD COLUMN model_protocol text NOT NULL DEFAULT '', ADD COLUMN model_name text NOT NULL DEFAULT '', ADD COLUMN model_base_url text NOT NULL DEFAULT '';
CREATE OR REPLACE FUNCTION capture_configuration_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='UPDATE' AND (NEW.version<OLD.version OR (NEW.version=OLD.version AND (NEW.agent_type IS DISTINCT FROM OLD.agent_type OR NEW.encrypted_api_key IS DISTINCT FROM OLD.encrypted_api_key OR NEW.model_connection_id IS DISTINCT FROM OLD.model_connection_id OR NEW.model_protocol IS DISTINCT FROM OLD.model_protocol OR NEW.model_name IS DISTINCT FROM OLD.model_name OR NEW.model_base_url IS DISTINCT FROM OLD.model_base_url))) THEN RAISE EXCEPTION 'configuration_version_conflict' USING ERRCODE='40001';END IF;
 INSERT INTO agent_configuration_versions(agent_config_id,version,agent_type,encrypted_api_key,model_connection_id,model_protocol,model_name,model_base_url) VALUES(NEW.id,NEW.version,NEW.agent_type,NEW.encrypted_api_key,NEW.model_connection_id,NEW.model_protocol,NEW.model_name,NEW.model_base_url) ON CONFLICT DO NOTHING;RETURN NEW;END $$;
